SELECT p.gender, CAST(a.admittime AS DATE) AS admission_date, i.careunit, COUNT(DISTINCT a.hadm_id) AS num_admissions, AVG(l.value) AS avg_spo2, MIN(l.value) AS min_spo2, MAX(l.value) AS max_spo2 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN icustays i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 82 AND p.anchor_year_group IN ('77–87') AND CAST(a.dischtime AS DATE) - CAST(a.admittime AS DATE) BETWEEN 1 AND 4 AND i.careunit IN ('ICU', 'non-ICU') AND l.itemid IN (SELECT itemid FROM d_labitems WHERE label = 'Spo2') GROUP BY p.gender, admission_date, i.careunit;